/* Local loader: injects ApexCharts from CDN when local file is requested.
   Keeps the original static path so templates don't 404. */
(function () {
  try {
    var url = 'https://cdn.jsdelivr.net/npm/apexcharts';
    var s = document.createElement('script');
    s.type = 'text/javascript';
    s.src = url;
    s.async = false; // try to preserve execution order
    var ref = document.getElementsByTagName('script')[0];
    if (ref && ref.parentNode) {
      ref.parentNode.insertBefore(s, ref);
    } else {
      document.head.appendChild(s);
    }
  } catch (e) {
    /* noop */
  }
})();
